type OrderStatus = "pending" | "paid" | "shipped";

interface Order {
  id: number;
  status: OrderStatus;
}

function ship(order: Order): string {
  order.status = "shipped";
  return `order #${order.id} ${order.status}`;
}

const order: Order = { id: 1042, status: "paid" };
console.log(ship(order));

